create extension if not exists pgcrypto;
create table public.shops(id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, name text not null, city text, country text default 'Congo', currency text not null default 'XAF', created_at timestamptz not null default now());
create table public.arrivals(id uuid primary key default gen_random_uuid(), shop_id uuid not null references public.shops(id) on delete cascade, code text not null, kind text not null check(kind in ('supplier_order','balloon')), origin_country text, supplier_name text, order_date date, received_date date, merchandise_cost numeric(14,2) not null default 0 check(merchandise_cost>=0), transport_cost numeric(14,2) not null default 0 check(transport_cost>=0), customs_cost numeric(14,2) not null default 0 check(customs_cost>=0), global_cost numeric(14,2) not null default 0 check(global_cost>=0), status text not null default 'draft', created_at timestamptz not null default now(), unique(shop_id,code));
create table public.products(id uuid primary key default gen_random_uuid(), shop_id uuid not null references public.shops(id) on delete cascade, arrival_id uuid references public.arrivals(id) on delete set null, name text not null, category text, brand text, size text, initial_sale_price numeric(14,2) not null default 0 check(initial_sale_price>=0), quantity_on_hand integer not null default 0 check(quantity_on_hand>=0), is_unique_piece boolean not null default false, status text not null default 'active' check(status in ('active','sold','archived')), created_at timestamptz not null default now());
create table public.sales(id uuid primary key default gen_random_uuid(), shop_id uuid not null references public.shops(id) on delete cascade, payment_method text not null check(payment_method in ('cash','mobile_money','card','bank_transfer','other')), total_amount numeric(14,2) not null default 0 check(total_amount>=0), sold_at timestamptz not null default now());
create table public.sale_items(id uuid primary key default gen_random_uuid(), sale_id uuid not null references public.sales(id) on delete cascade, product_id uuid not null references public.products(id), quantity integer not null default 1 check(quantity>0), initial_unit_price numeric(14,2) not null check(initial_unit_price>=0), sold_unit_price numeric(14,2) not null check(sold_unit_price>=0));
create table public.shop_expenses(id uuid primary key default gen_random_uuid(), shop_id uuid not null references public.shops(id) on delete cascade, category text not null, label text not null, amount numeric(14,2) not null check(amount>=0), expense_date date not null default current_date, recurring boolean not null default false, created_at timestamptz not null default now());
create index arrivals_shop_idx on public.arrivals(shop_id); create index products_shop_idx on public.products(shop_id); create index products_arrival_idx on public.products(arrival_id); create index sales_shop_sold_idx on public.sales(shop_id,sold_at desc); create index expenses_shop_date_idx on public.shop_expenses(shop_id,expense_date desc);
alter table public.shops enable row level security; alter table public.arrivals enable row level security; alter table public.products enable row level security; alter table public.sales enable row level security; alter table public.sale_items enable row level security; alter table public.shop_expenses enable row level security;
create policy shops_owner_all on public.shops for all to authenticated using ((select auth.uid())=owner_id) with check ((select auth.uid())=owner_id);
create policy arrivals_shop_member_all on public.arrivals for all to authenticated using (exists(select 1 from public.shops s where s.id=shop_id and s.owner_id=(select auth.uid()))) with check (exists(select 1 from public.shops s where s.id=shop_id and s.owner_id=(select auth.uid())));
create policy products_shop_member_all on public.products for all to authenticated using (exists(select 1 from public.shops s where s.id=shop_id and s.owner_id=(select auth.uid()))) with check (exists(select 1 from public.shops s where s.id=shop_id and s.owner_id=(select auth.uid())));
create policy sales_shop_member_all on public.sales for all to authenticated using (exists(select 1 from public.shops s where s.id=shop_id and s.owner_id=(select auth.uid()))) with check (exists(select 1 from public.shops s where s.id=shop_id and s.owner_id=(select auth.uid())));
create policy sale_items_shop_member_all on public.sale_items for all to authenticated using (exists(select 1 from public.sales v join public.shops s on s.id=v.shop_id where v.id=sale_id and s.owner_id=(select auth.uid()))) with check (exists(select 1 from public.sales v join public.shops s on s.id=v.shop_id where v.id=sale_id and s.owner_id=(select auth.uid())));
create policy expenses_shop_member_all on public.shop_expenses for all to authenticated using (exists(select 1 from public.shops s where s.id=shop_id and s.owner_id=(select auth.uid()))) with check (exists(select 1 from public.shops s where s.id=shop_id and s.owner_id=(select auth.uid())));
grant select,insert,update,delete on public.shops,public.arrivals,public.products,public.sales,public.sale_items,public.shop_expenses to authenticated;
